import sys

def check_consistency(s):
    n = len(s)
    for start in range(n):
        valid = True
        current = 1
        for i in range(n):
            if s[(start + i) % n] == 'E':
                if current != 1:
                    valid = False
                    break
            else:
                if current == 1:
                    current = 2
                else:
                    current = 1
        if valid:
            return "YES"
    return "NO"

input = sys.stdin.read().split()
t = int(input[0])
results = []
for i in range(1, t + 1):
    s = input[i]
    results.append(check_consistency(s))
print("\n".join(results))
